# Let's first do a keyword-based filter to identify potential flight booking issue dialogs
import re

booking_keywords = ['book', 'booking', 'reservation', 'reserv', 'itinerary', 'ticket', 'purchase', 'bought', 'buy']

def has_booking_keywords(dialog_text):
    text_lower = dialog_text.lower()
    return any(kw in text_lower for kw in booking_keywords)

# Filter dialogs that mention booking-related keywords
booking_dialogs_by_company = {}
for d in dataset:
    company = d['company_id']
    if company not in booking_dialogs_by_company:
        booking_dialogs_by_company[company] = []
    if has_booking_keywords(d['dialog']):
        booking_dialogs_by_company[company].append(d)

print("Dialogs mentioning booking keywords by company:")
for company, dialogs in sorted(booking_dialogs_by_company.items(), key=lambda x: -len(x[1])):
    print(f"  {company}: {len(dialogs)}")
